  // ── block 19 — dialogue ─────────────────────────────────────────────────
  "Hallo! Was möchtest du?": "¡Hola! ¿Qué te pongo?",
  "Ich möchte einen Kaffee, bitte.": "Querría un café, por favor.",
  "Sonst noch etwas?": "¿Algo más?",
  "Nein, danke.": "No, gracias.",
  "Möchtest du hier essen oder mitnehmen?": "¿Quieres comer aquí o para llevar?",
  "Ich nehm ihn mit, bitte.": "Para llevar, por favor.",
  "Das macht drei Euro fünfzig.": "Son tres euros con cincuenta.",
  "Hier, bitte. Danke schön!": "Aquí tienes. ¡Muchas gracias!",
  "Wie heißt du?": "¿Cómo te llamas?",
  "Ich heiße Alex.": "Me llamo Alex.",
  "Woher kommst du?": "¿De dónde eres?",
  "Ich komm aus England.": "Soy de Inglaterra.",
  "Seit wann bist du hier?": "¿Desde cuándo estás aquí?",
  "Seit zwei Monaten.": "Desde hace dos meses.",
  "Und wie gefällt es dir?": "¿Y qué te parece?",
  "Sehr gut. Die Leute sind nett.": "Muy bien. La gente es maja.",
  "Entschuldigung, wo ist der Bahnhof?": "Perdone, ¿dónde está la estación?",
  "Geradeaus und dann links.": "Todo recto y luego a la izquierda.",
  "Danke schön.": "Muchas gracias.",
  "Gern geschehen.": "De nada.",
  "Kann ich Ihnen helfen?": "¿Puedo ayudarle?",
  "Ja, ich such Wasser.": "Sí, busco agua.",
  "Dort hinten, neben der Kasse.": "Allí al fondo, al lado de la caja.",
  "Perfekt, danke.": "Perfecto, gracias.",
  "Wann stehst du auf?": "¿A qué hora te levantas?",
  "Ich steh um sieben Uhr auf.": "Me levanto a las siete.",
  "Trinkst du Kaffee?": "¿Tomas café?",
  "Ja, jeden Morgen.": "Sí, todas las mañanas.",
  "Hast du morgen Zeit?": "¿Tienes tiempo mañana?",
  "Ja, am Nachmittag.": "Sí, por la tarde.",
  "Wollen wir uns treffen?": "¿Quedamos?",
  "Ja, das klingt gut.": "Sí, suena bien.",
  "Möchtest du Kaffee oder Tee?": "¿Quieres café o té?",
  "Ich nehm einen Kaffee, bitte.": "Tomaré un café, por favor.",
  "Möchtest du auch Brot?": "¿Quieres pan también?",
  "Ja, ich hab Hunger.": "Sí, tengo hambre.",
  "Geh ich hier links oder rechts?": "¿Aquí voy a la izquierda o a la derecha?",
  "Hier rechts und dann geradeaus.": "Aquí a la derecha y luego todo recto.",
  "Bist du bald fertig? Wir wollten doch noch einkaufen.": "¿Terminas pronto? Íbamos a hacer la compra, ¿recuerdas?",
  "Zehn Minuten noch. Ich muss diese Liste zu Ende schreiben.": "Diez minutos más. Tengo que terminar de escribir esta lista.",
  "Gut, dann mach ich schon mal das Fenster zu und packe die Taschen.": "Vale, entonces voy cerrando la ventana y preparo las bolsas.",
  "Hast du Kleingeld für den Einkaufswagen?": "¿Tienes suelto para el carro de la compra?",
  "Nein, aber wir nehmen einfach den Korb. So viel brauchen wir nicht.": "No, pero cogemos la cesta y ya está. No necesitamos tanto.",
  "Komm rein! Die Schuhe kannst du gern anlassen.": "¡Pasa! Puedes dejarte los zapatos puestos.",
  "Schön hell hier. Seit wann wohnst du im dritten Stock?": "Qué luminoso. ¿Desde cuándo vives en el tercero?",
  "Seit zwei Monaten. Die Küche ist klein, aber sie reicht mir.": "Desde hace dos meses. La cocina es pequeña, pero me llega.",
  "Und der Balkon! Da bleib ich im Sommer gleich zum Essen.": "¡Y el balcón! En verano me quedo ahí mismo a cenar.",
  "Gern. Nur der Aufzug ist leider öfter kaputt als er fährt.": "Cuando quieras. Solo que el ascensor está averiado más a menudo de lo que funciona.",
  "Arbeitest du morgen im Büro oder im Homeoffice?": "¿Mañana trabajas en la oficina o desde casa?",
  "Im Büro. Wir planen das neue Projekt, da will ich dabei sein.": "En la oficina. Estamos planificando el proyecto nuevo y quiero estar.",
  "Wer erklärt dem Team eigentlich den Plan?": "¿Y quién le explica el plan al equipo?",
  "Die Chefin selbst, am Freitag um neun.": "La jefa en persona, el viernes a las nueve.",
  "Dann arbeite ich Freitag nur bis zwei und komme danach dazu.": "Entonces el viernes trabajo solo hasta las dos y me uno después.",
  "Hast du die Nachricht über das neue Schwimmbad gelesen?": "¿Has leído la noticia sobre la nueva piscina?",
  "Ja, heute Morgen in der Zeitung. Ich glaub aber nicht dass das klappt.": "Sí, esta mañana en el periódico. Pero no creo que salga adelante.",
  "Warum nicht? Ich finde die Idee eigentlich gut.": "¿Por qué no? A mí la idea me parece buena, la verdad.",
  "Zu teuer. Und ich glaub die Stadt hat das Geld nicht.": "Demasiado cara. Y creo que el ayuntamiento no tiene el dinero.",
  "Da hast du vielleicht recht. Mal sehen was daraus wird.": "Puede que tengas razón. A ver en qué queda.",
  "Entschuldigung, ich hab meine Tasche im Zug vergessen. Wer kann mir helfen?": "Perdone, me he dejado el bolso en el tren. ¿Quién puede ayudarme?",
  "Da sind Sie hier richtig. Welcher Zug war es denn?": "Ha venido al sitio correcto. ¿Qué tren era?",
  "Der um halb neun aus Hamburg. Die Tasche ist blau, mit meinem Regenschirm drin.": "El de las ocho y media desde Hamburgo. El bolso es azul, con mi paraguas dentro.",
  "Moment ... tatsächlich, die wurde gerade abgegeben. Haben Sie Ihren Pass dabei?": "Un momento... pues sí, lo acaban de entregar. ¿Lleva usted el pasaporte encima?",
  "Ja, zum Glück war der in meiner Jacke und nicht in der Tasche.": "Sí, por suerte estaba en la chaqueta y no en el bolso.",
  "Drei Gegner in der Mitte!": "¡Tres enemigos en el centro!",
  "Ich pushe von links.": "Yo pusheo por la izquierda.",
  "Vorsicht, einer campt in der Ecke.": "Cuidado, uno está campeando en la esquina.",
  "Hab ihn. Netter Frag, oder?": "Lo tengo. Buen frag, ¿eh?",
