  "Hast du dich schon daran gewöhnt?": "¿Ya te has acostumbrado?",
  "Noch nicht ganz, aber langsam wird es zur Gewohnheit.": "Del todo todavía no, pero poco a poco se va haciendo costumbre.",
  "Da ist es ja! Danke.": "¡Ahí está! Gracias.",
  "Du legst es wirklich jedes Mal woanders hin.": "De verdad que cada vez lo dejas en otro sitio.",
  "Kein Problem. Wann brauchst du es zurück?": "Sin problema. ¿Cuándo lo necesitas de vuelta?",
  "Spätestens heute Abend.": "Esta tarde como muy tarde.",
  "Nein, wir haben keine Milch mehr.": "No, se nos ha acabado la leche.",
  "Mach ich. Brauchst du sonst noch was?": "Lo haré. ¿Necesitas algo más?",
  "Super, ich nehm es gleich mit.": "Estupendo, me lo llevo ahora mismo.",
