  "Die kleine schwarze Box ganz oben im Regal.": "La caja negra pequeña de arriba del todo en la estantería.",
  "Ah ja, jetzt seh ich sie.": "Ah, sí, ahora la veo.",
  "Sie trägt eine rote Jacke und hat kurze blonde Haare.": "Lleva una chaqueta roja y tiene el pelo rubio y corto.",
  "Hat sie eine Brille?": "¿Lleva gafas?",
  "Nein, aber du erkennst sie sofort.": "No, pero la reconocerás enseguida.",
  "Es ist rund, dunkelblau und hat einen langen Griff.": "Es redondo, azul oscuro y tiene un mango largo.",
  "Ist es aus Metall?": "¿Es de metal?",
  "Nein, aus Holz.": "No, de madera.",
  "Ist das dasselbe Modell wie auf dem Bild?": "¿Es el mismo modelo que el de la foto?",
  "Fast. Das hier ist die größere Version.": "Casi. Este es la versión más grande.",
  "Ja, ich schau kurz nach.": "Sí, lo miro un momento.",
